window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5becb16864ff21e4"]={"versions": [{"id": "FIG-5becb16864ff21e4", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsmetamodellierung im Kontext der AUTOSAR Standardization Template (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Das Diagramm modelliert die strukturellen Mechanismen zur Referenzierung von benutzerdefinierten Spezifikationselementen und Dokumentationsobjekten innerhalb von Spezifikations- und Dokumentumfängen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Klassen & Spezialisierungen:</strong></li>\n<li><code>SpecificationScope</code>: Wurzel- bzw. Rahmenelement für Spezifikationsumfänge.</li>\n<li><code>SpecificationDocumentScope</code> (spezialisiert <code>SpecElementScope</code>): Repräsentiert den Dokumentenbereich einer Spezifikation.</li>\n<li><code>DocumentElementScope</code> (spezialisiert <code>SpecElementScope</code>): Repräsentiert den Elementbereich innerhalb eines Dokuments.</li>\n<li><code>Documentation</code> (spezialisiert <code>ARElement</code>): Dokumentationscontainer für benutzerdefinierte Dokumentation.</li>\n<li>Abstrakte Basisklasse <code>Traceable</code> (spezialisiert <code>MultilanguageReferrable</code>).</li>\n<li><code>TraceableText</code> (spezialisiert <code>Traceable</code>, <code>Identifiable</code>, <code>Paginateable</code>): Textuelle, rückverfolgbare Dokumentationseinheit.</li>\n<li><code>StructuredReq</code> (spezialisiert <code>Traceable</code>, <code>Identifiable</code>, <code>Paginateable</code>): Strukturierte Anforderung mit Attributen:</li>\n<li><code>+ appliesTo : standardNameEnum [0..*]</code></li>\n<li><code>+ date : DateTime</code></li>\n<li><code>+ importance : String</code></li>\n<li><code>+ issuedBy : String</code></li>\n<li><code>+ type : String</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Assoziationen & Kompositionen:</strong></li>\n<li>Komposition von <code>SpecificationScope</code> zu <code>SpecificationDocumentScope</code>: Rollenname <code>+specificationDocumentScope</code>, Multiplizität <code>0..*</code>.</li>\n<li>Komposition von <code>SpecificationDocumentScope</code> zu <code>DocumentElementScope</code>: Rollenname <code>+documentElementScope</code>, Multiplizität <code>0..*</code>.</li>\n<li>Gerichtete Assoziation von <code>SpecificationDocumentScope</code> zu <code>Documentation</code>: Rollenname <code>+customDocumentation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Gerichtete Assoziation von <code>DocumentElementScope</code> zu <code>Traceable</code>: Rollenname <code>+customDocumentElement</code>, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionssequenzen oder Laufzeit-Zustandsübergänge. Es beschreibt die deklarative Metamodellstruktur zur Verknüpfung von Spezifikations-Scopes mit konkreten Anforderungen (<code>StructuredReq</code>) oder Textblöcken (<code>TraceableText</code>) sowie Dokumentations-Elementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsvorgabe für AUTOSAR-Authoring-Tools und Modelltransformationen im Standardisierungsprozess:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>SpecificationDocumentScope</code> kann optional genau eine benutzerdefinierte Dokumentation (<code>customDocumentation</code>, <code>0..1</code>) referenzieren.</li>\n<li>Ein <code>DocumentElementScope</code> kann optional genau ein rückverfolgbares Element (<code>customDocumentElement</code>, <code>0..1</code>) referenzieren, das entweder als <code>TraceableText</code> oder als <code>StructuredReq</code> instanziiert ist.</li>\n<li><code>StructuredReq</code> erfordert die Beachtung des Aufzählungstyps <code>standardNameEnum</code> für das Multi-Value-Attribut <code>appliesTo</code>.</li>\n</ul>"}, {"id": "FIG-a1e7eeb84c54086c", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsmetamodellierung im Kontext der AUTOSAR Standardization Template (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Das Diagramm modelliert die strukturellen Mechanismen zur Referenzierung von benutzerdefinierten Spezifikationselementen und Dokumentationsobjekten innerhalb von Spezifikations- und Dokumentumfängen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Klassen & Spezialisierungen:</strong></li>\n<li><code>SpecificationScope</code>: Wurzel- bzw. Rahmenelement für Spezifikationsumfänge.</li>\n<li><code>SpecificationDocumentScope</code> (spezialisiert <code>SpecElementScope</code>): Repräsentiert den Dokumentenbereich einer Spezifikation.</li>\n<li><code>DocumentElementScope</code> (spezialisiert <code>SpecElementScope</code>): Repräsentiert den Elementbereich innerhalb eines Dokuments.</li>\n<li><code>Documentation</code> (spezialisiert <code>ARElement</code>): Dokumentationscontainer für benutzerdefinierte Dokumentation.</li>\n<li>Abstrakte Basisklasse <code>Traceable</code> (spezialisiert <code>MultilanguageReferrable</code>).</li>\n<li><code>TraceableText</code> (spezialisiert <code>Traceable</code>, <code>Identifiable</code>, <code>Paginateable</code>): Textuelle, rückverfolgbare Dokumentationseinheit.</li>\n<li><code>StructuredReq</code> (spezialisiert <code>Traceable</code>, <code>Identifiable</code>, <code>Paginateable</code>): Strukturierte Anforderung mit Attributen:</li>\n<li><code>+ appliesTo : standardNameEnum [0..*]</code></li>\n<li><code>+ date : DateTime</code></li>\n<li><code>+ importance : String</code></li>\n<li><code>+ issuedBy : String</code></li>\n<li><code>+ type : String</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Assoziationen & Kompositionen:</strong></li>\n<li>Komposition von <code>SpecificationScope</code> zu <code>SpecificationDocumentScope</code>: Rollenname <code>+specificationDocumentScope</code>, Multiplizität <code>0..*</code>.</li>\n<li>Komposition von <code>SpecificationDocumentScope</code> zu <code>DocumentElementScope</code>: Rollenname <code>+documentElementScope</code>, Multiplizität <code>0..*</code>.</li>\n<li>Gerichtete Assoziation von <code>SpecificationDocumentScope</code> zu <code>Documentation</code>: Rollenname <code>+customDocumentation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Gerichtete Assoziation von <code>DocumentElementScope</code> zu <code>Traceable</code>: Rollenname <code>+customDocumentElement</code>, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionssequenzen oder Laufzeit-Zustandsübergänge. Es beschreibt die deklarative Metamodellstruktur zur Verknüpfung von Spezifikations-Scopes mit konkreten Anforderungen (<code>StructuredReq</code>) oder Textblöcken (<code>TraceableText</code>) sowie Dokumentations-Elementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsvorgabe für AUTOSAR-Authoring-Tools und Modelltransformationen im Standardisierungsprozess:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>SpecificationDocumentScope</code> kann optional genau eine benutzerdefinierte Dokumentation (<code>customDocumentation</code>, <code>0..1</code>) referenzieren.</li>\n<li>Ein <code>DocumentElementScope</code> kann optional genau ein rückverfolgbares Element (<code>customDocumentElement</code>, <code>0..1</code>) referenzieren, das entweder als <code>TraceableText</code> oder als <code>StructuredReq</code> instanziiert ist.</li>\n<li><code>StructuredReq</code> erfordert die Beachtung des Aufzählungstyps <code>standardNameEnum</code> für das Multi-Value-Attribut <code>appliesTo</code>.</li>\n</ul>"}, {"id": "FIG-4a2abf46761191f8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsmetamodellierung im Kontext der AUTOSAR Standardization Template (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Das Diagramm modelliert die strukturellen Mechanismen zur Referenzierung von benutzerdefinierten Spezifikationselementen und Dokumentationsobjekten innerhalb von Spezifikations- und Dokumentumfängen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Klassen & Spezialisierungen:</strong></li>\n<li><code>SpecificationScope</code>: Wurzel- bzw. Rahmenelement für Spezifikationsumfänge.</li>\n<li><code>SpecificationDocumentScope</code> (spezialisiert <code>SpecElementScope</code>): Repräsentiert den Dokumentenbereich einer Spezifikation.</li>\n<li><code>DocumentElementScope</code> (spezialisiert <code>SpecElementScope</code>): Repräsentiert den Elementbereich innerhalb eines Dokuments.</li>\n<li><code>Documentation</code> (spezialisiert <code>ARElement</code>): Dokumentationscontainer für benutzerdefinierte Dokumentation.</li>\n<li>Abstrakte Basisklasse <code>Traceable</code> (spezialisiert <code>MultilanguageReferrable</code>).</li>\n<li><code>TraceableText</code> (spezialisiert <code>Traceable</code>, <code>Identifiable</code>, <code>Paginateable</code>): Textuelle, rückverfolgbare Dokumentationseinheit.</li>\n<li><code>StructuredReq</code> (spezialisiert <code>Traceable</code>, <code>Identifiable</code>, <code>Paginateable</code>): Strukturierte Anforderung mit Attributen:</li>\n<li><code>+ appliesTo: StandardNameEnum [0..*]</code></li>\n<li><code>+ date: DateTime</code></li>\n<li><code>+ importance: String</code></li>\n<li><code>+ issuedBy: String</code></li>\n<li><code>+ type: String</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Assoziationen & Kompositionen:</strong></li>\n<li>Komposition von <code>SpecificationScope</code> zu <code>SpecificationDocumentScope</code>: Rollenname <code>+specificationDocumentScope</code>, Multiplizität <code>0..*</code>.</li>\n<li>Komposition von <code>SpecificationDocumentScope</code> zu <code>DocumentElementScope</code>: Rollenname <code>+documentElementScope</code>, Multiplizität <code>0..*</code>.</li>\n<li>Gerichtete Assoziation von <code>SpecificationDocumentScope</code> zu <code>Documentation</code>: Rollenname <code>+customDocumentation</code>, Multiplizität <code>0..1</code>.</li>\n<li>Gerichtete Assoziation von <code>DocumentElementScope</code> zu <code>Traceable</code>: Rollenname <code>+customDocumentElement</code>, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionssequenzen oder Laufzeit-Zustandsübergänge. Es beschreibt die deklarative Metamodellstruktur zur Verknüpfung von Spezifikations-Scopes mit konkreten Anforderungen (<code>StructuredReq</code>) oder Textblöcken (<code>TraceableText</code>) sowie Dokumentations-Elementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsvorgabe für AUTOSAR-Authoring-Tools und Modelltransformationen im Standardisierungsprozess:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>SpecificationDocumentScope</code> kann optional genau eine benutzerdefinierte Dokumentation (<code>customDocumentation</code>, <code>0..1</code>) referenzieren.</li>\n<li>Ein <code>DocumentElementScope</code> kann optional genau ein rückverfolgbares Element (<code>customDocumentElement</code>, <code>0..1</code>) referenzieren, das entweder als <code>TraceableText</code> oder als <code>StructuredReq</code> instanziiert ist.</li>\n<li><code>StructuredReq</code> erfordert die Beachtung des Aufzählungstyps <code>StandardNameEnum</code> für das Multi-Value-Attribut <code>appliesTo</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-5becb16864ff21e4", "to": "FIG-a1e7eeb84c54086c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a1e7eeb84c54086c", "to": "FIG-4a2abf46761191f8", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>StructuredReq</code>: Typ des Attributs <code>appliesTo</code> von <code>standardNameEnum</code> in <code>StandardNameEnum</code> geändert (Großschreibung des Typnamens).</li>\n</ul>"}]};
